st.set_page_config(page_title="Pacific Lens · Global Market Atlas", page_icon="🌐", layout="wide")
st.markdown('''<style>
.block-container {padding:1rem 1rem 0; max-width:1800px;}
[data-testid="stHeader"] {background:rgba(255,255,255,.93);}
[data-testid="stSidebar"] {background:#f5f8fc;}
</style>''', unsafe_allow_html=True)
SYMBOLS = {"us": "^GSPC", "cn": "000001.SS", "jp": "^N225", "kr": "^KS11", "hk": "^HSI"}
ISO = {"USA": "us", "CHN": "cn", "JPN": "jp", "KOR": "kr", "HKG": "hk"}


@st.cache_data(ttl=900, show_spinner=False)
def market_history(symbol):
    """No credentials or synthetic fallback; keep local exchange session dates."""
    import yfinance as yf
    cutoff = datetime.now(timezone.utc).date().isoformat()
    frame = yf.Ticker(symbol).history(start="1990-01-01", end=cutoff,
                                      auto_adjust=False, actions=False, timeout=10)
    if frame is None or frame.empty:
        raise ValueError("Yahoo returned no history")
    s = frame["Close"].dropna()
    s = s[(s > 0) & (s < float("inf"))]
    s.index = s.index.tz_localize(None).normalize()
    s = s[~s.index.duplicated(keep="last")].sort_index()
    return [[d.date().isoformat(), round(float(v), 6)] for d, v in s.items()
            if d.date().isoformat() < cutoff]


@st.cache_data(ttl=86400, show_spinner=False)
def world_bank(indicator):
    # Annual actual observations; no forecast data and no interpolation.
    url = ("https://api.worldbank.org/v2/country/USA;CHN;JPN;KOR;HKG/indicator/"
           + indicator + f"?format=json&date=1990:{datetime.now(timezone.utc).year - 1}&per_page=1000")
    request = urllib.request.Request(url, headers={"User-Agent": "PacificLens-Research/1.0"})
    with urllib.request.urlopen(request, timeout=12) as response:
        payload = json.load(response)
    if not isinstance(payload, list) or len(payload) < 2 or not isinstance(payload[1], list):
        raise ValueError("World Bank data unavailable")
    result = {key: {} for key in SYMBOLS}
    for row in payload[1]:
        key = ISO.get(row.get("countryiso3code"))
        if key and isinstance(row.get("value"), (float, int)):
            result[key][row["date"]] = row["value"]
    return result


st.sidebar.title("Pacific Lens")
st.sidebar.caption("A five-market research atlas")
mode = st.sidebar.radio("Market data", ["Yahoo Finance", "Illustrative demo"])
st.sidebar.caption("Yahoo supplies historical daily closes. Today's UTC date is excluded to avoid partial sessions.")
if st.session_state.get("atlas_edition") != "hong-kong-v3":
    for key in ("prices", "errors", "fetched", "macro"):
        st.session_state.pop(key, None)
    st.session_state.atlas_edition = "hong-kong-v3"
if "prices" not in st.session_state:
    st.session_state.prices = {}
    st.session_state.errors = []
    st.session_state.fetched = None
if "macro" not in st.session_state:
    st.session_state.macro = json.loads(ASSETS["macro.json"])
load = st.sidebar.button("Load / refresh Yahoo data", type="primary", disabled=mode != "Yahoo Finance")
if load:
    market_history.clear()
    results, errors = {}, []
    with st.status("Loading Yahoo Finance and World Bank…", expanded=True) as status:
        with ThreadPoolExecutor(max_workers=3) as pool:
            futures = {pool.submit(market_history, symbol): key for key, symbol in SYMBOLS.items()}
            for future in as_completed(futures):
                key = futures[future]
                try:
                    results[key] = future.result()
                    st.write(f"{SYMBOLS[key]}: {len(results[key]):,} daily observations")
                except Exception as exc:
                    errors.append(f"{SYMBOLS[key]} unavailable ({type(exc).__name__}). Try again later.")
            for kind, indicator in [("cap", "CM.MKT.LCAP.CD"), ("growth", "NY.GDP.MKTP.KD.ZG")]:
                try:
                    st.session_state.macro[kind] = world_bank(indicator)
                except Exception as exc:
                    errors.append(f"World Bank {kind} refresh unavailable ({type(exc).__name__}); retained the dated annual snapshot.")
        st.session_state.prices = results
        st.session_state.errors = errors
        st.session_state.fetched = datetime.now(timezone.utc).isoformat(timespec="seconds")
        status.update(label="Data request complete", state="complete" if results else "error", expanded=False)
for message in st.session_state.errors:
    st.sidebar.warning(message)
st.sidebar.markdown("**Reading the charts**\n\nIndex performance is in local currency, excludes dividends, and uses shared dates at the start and end. GDP growth is a separate annual economic measure.")
st.sidebar.caption("Five market essays include historical context, dated sources and conditional outlooks.")
if mode == "Yahoo Finance" and not st.session_state.prices:
    st.info("The atlas is ready. Use ‘Load / refresh Yahoo data’ in the sidebar for real prices, or select ‘Illustrative demo’ to try the charts.")

profiles = json.loads(ASSETS["profiles.json"])
articles = json.loads(ASSETS["articles.json"])
data = {"profiles": profiles, "articles": articles, "prices": st.session_state.prices,
        "macro": st.session_state.macro, "demo": mode == "Illustrative demo",
        "fetched": st.session_state.fetched}
# Escape closing script tags in any authored content before embedding JSON.
serialized = json.dumps(data, ensure_ascii=False).replace("<", "\\u003c")
html = ASSETS["index.html"]
html = html.replace("/* APP_CSS */", ASSETS["styles.css"])
html = html.replace("/* APP_DATA */", "window.APP_DATA = " + serialized + ";")
html = html.replace("/* CHART_LIBRARY */", ASSETS["chart.umd.min.js"])
html = html.replace("/* APP_JS */", ASSETS["app.js"])
if hasattr(st, "iframe"):
    st.iframe(html, height="content", alt="Pacific Lens interactive market atlas")
else:
    components.html(html, height=1450, scrolling=True)
